import styled from '@emotion/styled';
import { TextButton } from 'components/UI';
import { theme } from 'theme';

type AlertType = 'info' | 'success' | 'warning' | 'error' | 'neutral' | 'AI';
type AlertEmphasis = 'medium' | 'low';
type AlertPosition = 'sticky' | 'inline' | 'toast';

interface StyledAlertProps {
  $type?: AlertType;
  $emphasis?: AlertEmphasis;
  $position?: AlertPosition;
  $noBorderRadius?: boolean;
}

export const StyledAlert = styled('div', {
  shouldForwardProp: (propName) =>
    !['$type', '$emphasis', '$position', '$noBorderRadius'].includes(propName),
})<StyledAlertProps>(
  ({
    $type = 'warning',
    $emphasis = 'medium',
    $position = 'inline',
    $noBorderRadius = false,
  }) => ({
    display: 'flex',
    gap: '12px',
    padding: '16px',
    borderRadius: '8px',
    minWidth: '320px',
    height: 'min-content',
    boxShadow: '0 0 4px 0 #00000029',
    flexDirection: 'column',
    ...($type === 'warning' && {
      backgroundColor: '#fff4e6',
      color: '#a65900',
      border: '1px solid #ffd499',
    }),
    ...($type === 'info' && {
      backgroundColor: '#e6f2ff',
      color: '#006edb',
      border: '1px solid #a1d0ff',
    }),
    ...($type === 'success' && {
      backgroundColor: '#e6f9e6',
      color: '#007800',
      border: '1px solid #99e699',
    }),
    ...($type === 'error' && {
      backgroundColor: '#fee2e2',
      color: '#b91c1c',
      border: '1px solid #fca5a5',
    }),
    ...($type === 'neutral' && {
      backgroundColor: '#e7e7e7',
      color: '#141414',
      boxShadow: 'none',
    }),
    ...($type === 'AI' && {
      backgroundColor: '#F0F9FF',
      color: '#141414',
      border: '1px solid #A1D0FF',
      padding: '13px',
      borderRadius: '16px',
    }),
    ...($emphasis === 'low' && {
      backgroundColor: '#f6f6f6',
      '&&': {
        borderLeft: '4px solid',
      },
    }),
    ...($position === 'sticky' && {
      position: 'sticky',
      top: 0,
      left: 0,
      right: 0,
      zIndex: 1000,
      borderRadius: 0,
    }),
    ...($position === 'inline' && {
      boxShadow: 'none',
      '&&': {
        border: 'none',
      },
    }),
    ...($noBorderRadius && { borderRadius: '0' }),
    ...($type === 'neutral' &&
      $position === 'sticky' && {
        borderRadius: '8px',
      }),
    ...($type === 'warning' &&
      $emphasis === 'low' && {
        color: '#d47300',
      }),
    ...($type === 'info' &&
      $emphasis === 'low' && {
        color: '#006edb',
      }),
    ...($type === 'success' &&
      $emphasis === 'low' && {
        color: '#009900',
      }),
    ...($type === 'error' &&
      $emphasis === 'low' && {
        color: '#d62222',
      }),
    ...($type === 'AI' &&
      $emphasis === 'low' && {
        color: '#0A0A0A',
      }),
    ...($type === 'neutral' &&
      $emphasis === 'low' && {
        '&&': {
          borderLeft: '4px solid #141414',
          backgroundColor: '#1414140A',
        },
      }),
  }),
);

export const StyledAlertBody = styled.div({
  width: '100%',
  minWidth: '200px',
  minHeight: '24px',
});

export const StyledAlertTitle = styled.p({
  fontFamily: theme.fonts.paragraph,
  fontWeight: 'bold',
  fontSize: '14px',
  lineHeight: '24px',
  margin: 0,
});

export const StyledAlertMessage = styled.div({
  display: 'flex',
  gap: '8px',
  justifyContent: 'space-between',
  alignItems: 'center',
});

interface SyledMessageContentProps {
  $iaAlertType?: boolean;
}

export const SyledMessageContent = styled('span', {
  shouldForwardProp: (propName) => propName !== '$iaAlertType',
})<SyledMessageContentProps>(({ $iaAlertType }) => ({
  fontFamily: theme.fonts.paragraph,
  fontSize: '14px',
  color: '#141414',
  lineHeight: '24px',
  ...($iaAlertType && {
    paddingTop: '8px',
    fontFamily: 'var(--font-family-body, "Work Sans")',
    fontSize: 'var(--size-paragraph-body-small, 14px)',
    fontStyle: 'normal',
    fontWeight: '400',
    lineHeight: '140%',
    background:
      'linear-gradient(90deg, #0973B9 0%, var(--color-fg-neutral_primary, #141414) 10.09%)',
    WebkitBackgroundClip: 'text',
    backgroundClip: 'text',
    WebkitTextFillColor: 'transparent',
    color: '#0973B9',
  }),
}));

export const StyledContentWrapper = styled.div({
  display: 'flex',
  flexDirection: 'column',
});

export const StyledAlertActionButtons = styled.div({
  display: 'flex',
  gap: '8px',
});

export const StyledAlertCloseButton = styled(TextButton)({
  backgroundColor: '#1414141a',
  borderRadius: '512px',
  width: '24px',
  height: '24px',
  minWidth: '24px',
  marginLeft: 'auto',
});

export const StyledAlertExpandedMessage = styled.div({
  paddingLeft: '36px',
  fontFamily: 'Work Sans, sans-serif',
  fontSize: '14px',
  color: '#141414',
});

export const StyledAlertExpandedMessageContainer = styled.div({
  display: 'flex',
  justifyContent: 'space-between',
  alignItems: 'center',
  width: '100%',
  gap: '12px',
});

interface StyledAlertAttributionProps {
  $iaAlertType?: boolean;
}

export const StyledAlertAttribution = styled('span', {
  shouldForwardProp: (propName) => propName !== '$iaAlertType',
})<StyledAlertAttributionProps>(({ $iaAlertType }) => ({
  display: 'none',
  fontFamily: theme.fonts.paragraph,
  fontWeight: 400,
  fontStyle: 'Regular',
  fontSize: '12px',
  lineHeight: '18px',
  letterSpacing: '0px',
  color: '#67665F',
  ...($iaAlertType && {
    display: 'block',
  }),
}));
